const freshDraft=()=>({doc:'',client:'',phone:'',email:'',plate:'',mode:'',claim:'',brand:'',model:'',color:'',year:'',vin:'',km:'',fuel:'',body:'V3',view:'01',check:Object.fromEntries(ALL_CHECK.map(item=>[item,'NO'])),notes:{},drawings:{},drawingsV:2,flags:[],photos:[],diagnosis:'',diagnosisPhoto:'',signature:'',accept:false});
const STORAGE_KEY='parautosPrototypeV3';
const storedRaw=localStorage.getItem(STORAGE_KEY);
function syncParts(o){if(o.noParts){o.parts=[];return}
 const prev=new Map((o.parts||[]).map(p=>[String(p.name||'').trim(),p]));
 o.parts=(o.quoteParts||[]).filter(q=>String(q.d||'').trim()).map(q=>{const k=String(q.d).trim(),p=prev.get(k);
  return{name:k,qty:q.q??1,status:p?p.status:'PENDIENTE_SOLICITAR',updated:p?.updated}})}
function normalizeState(s){
 const x=s&&typeof s==='object'?s:{};
 x.currentUser=null;
 x.orders=Array.isArray(x.orders)?x.orders:[];
  x.draft={...freshDraft(),...(x.draft||{})};x.draft.check||={};ALL_CHECK.forEach(item=>{if(!x.draft.check[item])x.draft.check[item]='NO'});
 x.draft.drawings||={};x.draft.photos||=[];x.audit||=[];
 if(x.draft.drawingsV!==2){x.draft.drawings={};x.draft.drawingsV=2;}
 x.draft.flags=Array.isArray(x.draft.flags)?x.draft.flags:[];
 x.orders.forEach(o=>{if(o.brand)o.brand=String(o.brand).toUpperCase();if(o.model)o.model=String(o.model).toUpperCase();
 o.labor=(Array.isArray(o.labor)?o.labor:[]).map(x=>{if(x.ok!==undefined)x.ok=(x.ok===true||x.ok==='CONFORME');return x});o.quoteParts=Array.isArray(o.quoteParts)?o.quoteParts:[];o.parts=Array.isArray(o.parts)?o.parts:[]});
 if(x.draft.brand)x.draft.brand=String(x.draft.brand).toUpperCase();
 if(x.draft.model)x.draft.model=String(x.draft.model).toUpperCase();
 x.step=x.step||1;x.route=x.route||'dashboard';x.selected=x.selected||x.orders[0]?.id||1;x.tab=x.tab||'summary';
 return x;
}
let state=normalizeState(storedRaw?JSON.parse(storedRaw):{orders:seed,draft:freshDraft(),step:1,route:'dashboard',selected:1,tab:'summary',audit:[],updatedAt:0});
let quoteFocusRequested=false;
let reportTab='dashboard';
if(storedRaw&&!state.updatedAt)state.updatedAt=1;
let serverConnected=false,syncTimer=null,syncing=false;
const persistLocal=()=>Api.persist();
const toast=t=>{const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)};
function syncText(){Api.syncLabel()}
const save=()=>{state.updatedAt=Date.now();persistLocal();syncText()};
async function hydrateFromServer(){await Api.refresh()}
addEventListener('online',async()=>{await hydrateFromServer();toast(serverConnected?'Conexión recuperada · datos sincronizados':'Conexión recuperada · servidor no disponible')});addEventListener('offline',()=>{serverConnected=false;syncText();toast('Sin conexión · seguiremos guardando en este dispositivo')});
const cls=s=>s==='COTIZACION_PENDIENTE'?'red':s==='ESPERA_APROBACION'||s==='ESPERA_REPUESTOS'?'amber':s==='EN_REPARACION'?'blue':s==='LISTA_PARA_ENTREGA'||s==='ENTREGADA'?'green':'';
const isAdmin=()=>state.currentUser?.idRol===1;
const adminRoute=route=>['reports','audit'].includes(route);
function setRoute(r){if(adminRoute(r)&&!isAdmin()){toast('Esta sección está disponible solo para administradores.');r='dashboard'}state.route=r;if(r==='new'&&!state.step)state.step=1;save();render()}
$$('[data-route]').forEach(b=>b.onclick=()=>setRoute(b.dataset.route));
addEventListener('keydown',e=>{
 if(e.key==='Escape'&&damageExpanded){e.preventDefault();setDamageExpanded(false);return;}
 if(e.key==='Escape'&&e.target.matches('input,textarea,select,[contenteditable="true"]')){e.preventDefault();e.target.blur();return;}
 if(!e.altKey||e.ctrlKey||e.shiftKey||e.metaKey||state.route!=='detail')return;
 if(e.target.matches('input,textarea,select,[contenteditable="true"]'))return;
 const tab={1:'summary',2:'quote',3:'parts',4:'control',5:'audit'}[e.key];
 if(!tab)return;
 e.preventDefault();if(tab==='quote'&&state.tab!==tab)quoteFocusRequested=true;state.tab=tab;save();detail();
});
const setNav=open=>{const s=$('.sidebar'),b=$('#menuButton');s.classList.toggle('open',open);b.setAttribute('aria-expanded',open?'true':'false');if(open){const f=s.querySelector('[data-route]');f&&f.focus({preventScroll:true})}};
$('#menuButton').onclick=()=>setNav(!$('.sidebar').classList.contains('open'));
addEventListener('click',e=>{const s=$('.sidebar');if(!s.classList.contains('open'))return;if(e.target.closest('.sidebar,#menuButton'))return;setNav(false)});
addEventListener('keydown',e=>{if(e.key!=='Escape'||!$('.sidebar').classList.contains('open'))return;setNav(false);$('#menuButton').focus()});

let _statusW=0;
function statusColumnWidth(){if(_statusW)return _statusW;const r=document.createElement('div');r.className='status-ruler';r.style.cssText='position:absolute;left:-9999px;top:0;visibility:hidden;pointer-events:none';r.innerHTML=Object.values(STAT).map(x=>`<span class="status ${cls(x)}">${x}</span>`).join('');document.body.appendChild(r);_statusW=Math.max(...[...r.children].map(e=>e.offsetWidth));r.remove();return _statusW;}
function render(){if(adminRoute(state.route)&&!isAdmin())state.route='dashboard';document.documentElement.style.setProperty('--status-w',statusColumnWidth()+'px');const titles={dashboard:'Panel principal',new:'Nueva orden',orders:'Órdenes',quotes:'Cotizaciones',parts:'Repuestos',reports:'Dashboard y reportes',audit:'Auditoría',detail:'Detalle de orden'};$('#topTitle').textContent=titles[state.route]||'PARAUTOS';$$('[data-route]').forEach(x=>x.classList.toggle('active',x.dataset.route===state.route));setNav(false);const pending=state.orders.filter(o=>o.quote==='PENDIENTE').length;$('#alertCount').textContent=pending;({dashboard:dashboard,new:wizard,orders:orders,quotes:quotes,parts:parts,reports:reports,audit:audit,detail:detail}[state.route]||dashboard)();syncText()}
function head(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function dashboard(){const counts={q:state.orders.filter(o=>o.status==='COTIZACION_PENDIENTE').length,a:state.orders.filter(o=>o.status==='ESPERA_APROBACION').length,p:state.orders.filter(o=>o.status==='ESPERA_REPUESTOS').length,r:state.orders.filter(o=>o.status==='EN_REPARACION').length};
const greeting = state.currentUser ? `Buenos días, ${state.currentUser.nombres.split(' ')[0]}` : 'Buenos días';
$('#app').innerHTML=head(greeting,'Vista operativa del taller actualizada en este dispositivo.',`<button class="btn primary" data-go="new">＋ Nueva orden</button>`)+`<div class="cards"><div class="card metric"><small>Cotizaciones pendientes</small><strong>${counts.q}</strong></div><div class="card metric amber"><small>Pendientes de aprobación</small><strong>${counts.a}</strong></div><div class="card metric blue"><small>Espera de repuestos</small><strong>${counts.p}</strong></div><div class="card metric green"><small>En reparación</small><strong>${counts.r}</strong></div></div><div class="grid-2"><section class="card"><div class="card-header"><h2>Prioridades del taller</h2><button class="btn small" data-go="orders">Ver todas</button></div>${state.orders.slice(0,5).map(orderRow).join('')}</section><section class="card"><div class="card-header"><h2>Distribución de casos</h2></div><div class="card-body">${Object.entries(STAT).slice(0,5).map(([k,v])=>{const n=state.orders.filter(o=>o.status===k).length;return `<div class="chart-row"><span>${v}</span><div class="bar"><i style="width:${n*25}%"></i></div><b>${n}</b></div>`}).join('')}</div></section></div>`;wireRoutes();}
function orderRow(o){return `<div class="list-row"><span class="vehicle-tag">🚗</span><div><strong>${o.brand} ${o.model} · ${o.color}</strong><small>${o.plate} · ${o.number}</small></div><div><strong>${o.mode}</strong><small>${o.body?BODIES.find(b=>b.id===o.body)?.name:''}</small></div><button class="status ${cls(o.status)}" data-open="${o.id}">${STAT[o.status]}</button></div>`}
function wireRoutes(){$$('[data-go]').forEach(b=>b.onclick=()=>setRoute(b.dataset.go));$$('[data-open]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.open;state.tab=b.dataset.goto||'summary';setRoute('detail')})}
function orders(){ $('#app').innerHTML=head('Órdenes del taller','Busca como trabaja el equipo: marca, modelo, color o carrocería.',`<button class="btn primary" data-go="new">＋ Nueva orden</button>`)+`<div class="filters"><div class="field"><input id="search" placeholder="Ej. Subaru roja, Hilux blanca o ABC-240"></div><div class="field"><select id="fMode"><option value="">Todas las modalidades</option>${['Particular','Mapfre','La Positiva','Rímac','Pacífico'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><select id="fState"><option value="">Todos los estados</option>${Object.entries(STAT).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><button class="btn" id="clearFilters">Limpiar</button></div><section class="card" id="orderList">${state.orders.map(orderRow).join('')}</section>`;wireRoutes();const filter=()=>{const q=$('#search').value.toLowerCase(),m=$('#fMode').value,s=$('#fState').value;$('#orderList').innerHTML=state.orders.filter(o=>`${o.brand} ${o.model} ${o.color} ${o.plate} ${o.number} ${o.mode}`.toLowerCase().includes(q)&&(!m||o.mode===m)&&(!s||o.status===s)).map(orderRow).join('')||'<div class="empty">No hay coincidencias.</div>';wireRoutes()};$('#search').oninput=filter;$('#fMode').onchange=filter;$('#fState').onchange=filter;$('#clearFilters').onclick=()=>{search.value='';fMode.value='';fState.value='';filter()}}
function shell(content){$('#app').innerHTML=`<div class="wizard"><div class="wizard-top"><div class="wizard-meta"><strong>${state.draft.plate||'Nueva orden'} · ${STEPS[state.step-1]}</strong><small>${state.step} de ${STEPS.length} · Guardado automático</small></div><div class="steps">${STEPS.map((_,i)=>`<i class="step ${i+1<state.step?'done':i+1===state.step?'active':''}"></i>`).join('')}</div></div><section class="card wizard-card">${content}</section></div><div class="wizard-actions"><button class="btn draft-label" id="draftBtn">Guardar borrador</button><div>${state.step>1?'<button class="btn" id="backBtn">← Anterior</button>':''}<button class="btn primary" id="nextBtn">${state.step===STEPS.length?'Confirmar y crear orden':'Continuar →'}</button></div></div>`;$('#draftBtn').onclick=()=>{capture();save();toast('Borrador guardado')};$('#backBtn')?.addEventListener('click',()=>{capture();state.step--;save();wizard()});$('#nextBtn').onclick=nextStep;$('.wizard-card').onkeydown=e=>{if(e.key!=='Enter'||e.shiftKey||e.ctrlKey||e.altKey||e.metaKey||e.target.matches('button,input[type="file"]'))return;e.preventDefault();$('#nextBtn').click()}}
function capture(){const d=state.draft;$$('[data-bind]').forEach(e=>d[e.dataset.bind]=e.type==='checkbox'?e.checked:e.value);save()}
function wizard(){const d=state.draft;if(state.step===1)shell(`<div class="section-title"><span>1</span><div><h2>Cliente, vehículo y condiciones de ingreso</h2><small class="hint">Los campos con * son obligatorios.</small></div></div><div class="form-grid"><div class="field"><label>DNI o RUC *</label><input data-bind="doc" value="${d.doc}" placeholder="Documento" id="docInput" inputmode="numeric" pattern="[0-9]*" oninput="this.value=this.value.replace(/[^0-9]/g,'')"></div><div class="field"><label>Cliente</label><input data-bind="client" value="${d.client}" placeholder="Nombre o razón social"></div><div class="field"><label>Celular</label><input data-bind="phone" value="${d.phone}" inputmode="numeric" pattern="[0-9]*" oninput="this.value=this.value.replace(/[^0-9]/g,'')"></div><div class="field"><label>Correo</label><input data-bind="email" value="${d.email}" type="email"></div><div class="field"><label>Placa *</label><input data-bind="plate" value="${d.plate}" placeholder="ABC123" maxlength="9" style="text-transform:uppercase" id="plateInput" oninput="onPlateInput(this)" onchange="onPlateChange(this)"><small class="hint">Formatos: ABC-123 · NG-1234 · E ABC-789 · CD-0123</small></div><div class="field"><label>Modalidad *</label><select data-bind="mode"><option value="">Selecciona</option>${['Particular','Mapfre','La Positiva','Rímac','Pacífico'].map(x=>`<option ${d.mode===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Marca *</label><input data-bind="brand" value="${d.brand}" list="brands" placeholder="Ej. TOYOTA" style="text-transform:uppercase" oninput="this.value=this.value.toUpperCase()"><datalist id="brands"><option>TOYOTA</option><option>SUBARU</option><option>MITSUBISHI</option><option>HINO</option><option>HYUNDAI</option></datalist></div><div class="field"><label>Modelo *</label><input data-bind="model" value="${d.model}" placeholder="Ej. COROLLA" style="text-transform:uppercase" oninput="this.value=this.value.toUpperCase()"></div><div class="field"><label>Color *</label><select data-bind="color"><option value="">Selecciona</option>${['Blanco','Negro','Gris','Plata','Rojo','Azul','Verde','Amarillo','Beige','Marrón','Naranja','Otro'].map(x=>`<option ${d.color===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Carrocería *</label><select data-bind="body">${BODIES.map(x=>`<option value="${x.id}" ${d.body===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="field"><label>Kilometraje (km)</label><input data-bind="km" value="${d.km}" inputmode="numeric" pattern="[0-9]*" oninput="this.value=this.value.replace(/[^0-9]/g,'')"></div><div class="field"><label>Combustible</label><select data-bind="fuel"><option value="">No registrado</option>${['Vacío','1/4','1/2','3/4','Lleno'].map(x=>`<option ${d.fuel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Año</label><input data-bind="year" value="${d.year}" placeholder="Ej. 2026" inputmode="numeric" maxlength="4" oninput="this.value=this.value.replace(/[^0-9]/g,'')"></div><div class="field"><label>VIN</label><input data-bind="vin" value="${d.vin}" placeholder="17 caracteres" maxlength="17" style="text-transform:uppercase" oninput="this.value=this.value.toUpperCase().replace(/[^A-Z0-9]/g,'')"></div><div class="field full"><label>Número de siniestro</label><input data-bind="claim" value="${d.claim}" placeholder="Requerido según modalidad"></div></div>`);
else if(state.step===2){const answered=Object.keys(d.check).filter(k=>d.check[k]).length;shell(`<div class="section-title"><span>✓</span><div><h2>Checklist de recepción</h2><small class="hint">${answered} de 44 respondidos · todos son obligatorios.</small></div></div>${Object.entries(CHECK).map(([cat,items],ci)=>`<details class="category" ${ci===0?'open':''}><summary>${cat}<span>${items.filter(x=>d.check[x]).length}/${items.length}</span></summary>${items.map((x,i)=>{const id=`c${ci}_${i}`;return `<div class="check-row"><strong>${x}</strong><div class="segmented"><input type="radio" id="${id}y" name="${id}" value="SI" ${d.check[x]==='SI'?'checked':''} data-check="${x}"><label for="${id}y">Sí</label><input type="radio" id="${id}n" name="${id}" value="NO" ${d.check[x]==='NO'?'checked':''} data-check="${x}"><label for="${id}n">No</label></div><input placeholder="Observación (opcional)" value="${d.notes[x]||''}" data-note="${x}"></div>`}).join('')}</details>`).join('')}`);$$('[data-check]').forEach(e=>e.onchange=()=>{d.check[e.dataset.check]=e.value;save()});$$('[data-note]').forEach(e=>e.oninput=()=>{d.notes[e.dataset.note]=e.value;save()})}
else if(state.step===3)considerStep();else if(state.step===4)damageStep();else if(state.step===5)evidenceStep();else if(state.step===6)diagnosisStep();else summaryStep();}
function considerStep(){const d=state.draft,total=ALL_FLAGS.length,has=f=>d.flags.includes(f);
shell(`<div class="section-title"><span>!</span><div><h2>Consideraciones de recepción</h2><small class="hint" id="flagHint"></small></div></div><div class="flag-meter"><b id="flagCount">0/${total}</b><div class="bar"><i id="flagBar" style="width:0%"></i></div><small class="hint">Ninguna es obligatoria</small></div><div class="flag-groups">${RECEPTION_FLAGS.map(([g,items])=>`<section class="flag-group"><header><span>${g}</span><em>${items.filter(has).length}/${items.length}</em></header><div class="flag-list">${items.map(x=>`<label class="flag-row${has(x)?' on':''}"><input type="checkbox" data-flag="${x}" ${has(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></section>`).join('')}</div><div class="flag-preview"><h3>Así se imprimirá en la hoja de entrada</h3><small class="hint">Campo OBSERVACIONES</small><p id="flagPrev"></p><div class="important" id="flagWarn" style="margin-top:12px"></div></div>`);
const refresh=()=>{const m=d.flags.length,pct=total?m*100/total:0,p=shObsText(d.flags);
$('#flagHint').textContent=`${m} de ${total} marcadas · se imprimen en el campo OBSERVACIONES de la hoja de entrada.`;
$('#flagCount').textContent=`${m}/${total}`;
$('#flagBar').style.width=pct+'%';
$$('.flag-group').forEach(g=>{const items=[...g.querySelectorAll('[data-flag]')].map(i=>i.dataset.flag);g.querySelector('em').textContent=items.filter(f=>d.flags.includes(f)).length+'/'+items.length});
$('#flagPrev').textContent=p.text||'Sin condiciones marcadas.';
const w=$('#flagWarn');w.style.display=p.extra?'':'none';w.innerHTML=p.extra?`<strong>Atención:</strong> entran ${p.shown} de ${p.total} condiciones. Las ${p.extra} restantes quedan registradas en el sistema pero no se imprimen en la hoja de entrada.`:'';
};
$$('[data-flag]').forEach(e=>e.onchange=()=>{d.flags=e.checked?[...new Set([...d.flags,e.dataset.flag])]:d.flags.filter(f=>f!==e.dataset.flag);e.closest('.flag-row').classList.toggle('on',e.checked);refresh();save()});
refresh();}

const PLATE_RULES=[
 [/^EPA\d{3}$/,'Policía Nacional',s=>'EPA-'+s.slice(3)],
 [/^E[A-Z]{3}\d{3}$/,'Especial · Gubernamental / Emergencia',s=>'E '+s.slice(1,4)+'-'+s.slice(4)],
 [/^E[A-Z]{2}\d{3}$/,'Especial · Gubernamental / Emergencia',s=>'E '+s.slice(1,3)+'-'+s.slice(3)],
 [/^(?:CD|CC)\d{4}$/,'Diplomático / Gracia',s=>s.slice(0,2)+'-'+s.slice(2)],
 [/^PR\d{3}$/,'Rotativa / Exhibición',s=>'PR-'+s.slice(2)],
 [/^[A-Z]{2}\d{4}$/,'Moto / Mototaxi',s=>s.slice(0,2)+'-'+s.slice(2)],
 [/^[A-Z]{2}\d{5}$/,'Mototaxi / Trimoto',s=>s.slice(0,2)+'-'+s.slice(2)],
 [/^[A-Z]\d[A-Z]\d{4}$/,'Carga / Remolque / Turismo',s=>s.slice(0,3)+'-'+s.slice(3)],
 [/^[A-Z]\d[A-Z]\d{3}$/,'Carga / Mercancía',s=>s.slice(0,3)+'-'+s.slice(3)],
 [/^[A-Z]{3}\d{4}$/,'Ordinaria',s=>s.slice(0,3)+'-'+s.slice(3)],
 [/^[A-Z]{3}\d{3}$/,'Ordinaria',s=>s.slice(0,3)+'-'+s.slice(3)]];
function plateRaw(raw){return String(raw||'').replace(/[^0-9A-Za-z]/g,'').toUpperCase();}
function normalizePlate(raw){const s=plateRaw(raw);for(const[re,type,fmt]of PLATE_RULES){if(re.test(s))return{ok:true,raw:s,value:fmt(s),type}}return{ok:false,raw:s,value:String(raw||'').toUpperCase().trim(),type:null}}
function onPlateInput(el){const n=normalizePlate(el.value);el.value=n.ok?n.value:plateRaw(el.value);el.dataset.plateType=n.ok?n.type:'';}
function onPlateChange(el){const n=normalizePlate(el.value);if(n.ok)toast('Placa válida · '+n.type);else if(n.raw)toast('Placa guardada como '+n.raw+' (formato no reconocido)');}
function validateStep1(d){const p=normalizePlate(d.plate);
 if(!d.doc||!/^\d{8}$|^\d{11}$/.test(d.doc))return{level:'error',msg:'El DNI (8 dígitos) o RUC (11 dígitos) es obligatorio.'};
 if(d.phone&&!/^\d{7,15}$/.test(d.phone))return{level:'error',msg:'El celular debe tener entre 7 y 15 dígitos.'};
 if(!p.raw)return{level:'error',msg:'La placa es obligatoria.'};
 if(p.raw.length<5)return{level:'error',msg:'La placa es demasiado corta. Revisa los caracteres (ej. ABC-123).'};
 if(!p.ok)return{level:'warn',msg:'El formato de la placa no coincide con los estándares habituales.\n\nTexto ingresado: '+p.raw+'\n\nEjemplos válidos: ABC-123, NG-1234, E ABC-789, CD-0123.\n\n¿Está seguro de que es correcta?'};
 if(d.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email))return{level:'error',msg:'Correo electrónico inválido.'};
 if(d.km&&!/^\d{1,7}$/.test(d.km))return{level:'error',msg:'El kilometraje debe ser numérico.'};
 if(d.vin&&!/^[A-HJ-NPR-Z0-9]{17}$/.test(d.vin))return{level:'error',msg:'El VIN debe tener exactamente 17 caracteres alfanuméricos.'};
 if(d.year&&!/^(19|20)\d{2}$/.test(d.year))return{level:'error',msg:'El año debe tener 4 dígitos (1900-2099).'};
 if(!d.brand)return{level:'error',msg:'La marca es obligatoria.'};
 if(!d.model)return{level:'error',msg:'El modelo es obligatorio.'};
 if(!d.color)return{level:'error',msg:'El color es obligatorio.'};
 if(!d.body)return{level:'error',msg:'La carrocería es obligatoria.'};
 if(!d.mode)return{level:'error',msg:'La modalidad es obligatoria.'};
 if(d.mode!=='Particular'&&!d.claim)return{level:'error',msg:'El número de siniestro es obligatorio para modalidades con aseguradora.'};
 return{level:'ok',msg:p.type?'Placa válida · '+p.type:'Placa válida',plate:p.value};}
function nextStep(){capture();const d=state.draft;if(state.step===1){const v=validateStep1(d);if(v.level==='error')return toast(v.msg);if(v.level==='warn'&&!confirm(v.msg))return;d.plate=v.plate||normalizePlate(d.plate).value;toast(v.msg);}if(state.step===2&&ALL_CHECK.some(x=>!d.check[x]))return toast(`Faltan ${ALL_CHECK.filter(x=>!d.check[x]).length} elementos del checklist`);if(state.step<STEPS.length){state.step++;save();wizard()}else createOrder()}
function damageStep(){const d=state.draft,view=VIEWS.find(v=>v[0]===d.view)||VIEWS[0];shell(`<div class="section-title"><span>✎</span><div><h2>Daños visibles</h2><small class="hint">Los trazos azules se guardan por carrocería y vista.</small></div></div><div class="damage-label">Carrocería</div><div class="body-picker">${BODIES.map(b=>`<button class="${d.body===b.id?'active':''}" data-body="${b.id}">${b.name}</button>`).join('')}</div><div class="damage-view-mobile"><div><small>Vista actual</small><strong id="activeViewName">${view[1]}</strong></div><div><button class="btn small" id="previousDamageView">← Anterior</button><button class="btn small" id="nextDamageView">Siguiente →</button></div></div><div class="view-tabs">${VIEWS.map(v=>`<button class="${d.view===v[0]?'active':''} ${d.drawings[`${d.body}-${v[0]}`]?.length?'marked':''}" data-view="${v[0]}">${v[1]}</button>`).join('')}</div><div id="damageEditor" class="damage-editor${damageExpanded?' is-fullscreen':''}"><div class="damage-fullscreen-head"><div><small>Edición de daños</small><strong>${BODIES.find(b=>b.id===d.body)?.name} · <span id="fullViewName">${view[1]}</span></strong></div><button class="btn small" id="exitDamageFullscreen">✕ Salir</button></div><div class="canvas-wrap"><img src="assets/${d.body}-${d.view}.png" alt="Vista ${view[1]} del vehículo"><canvas id="damageCanvas"></canvas><div class="rotate-device"><strong>Gira el dispositivo</strong><span>Esta vista lateral se edita en orientación horizontal.</span></div></div><div class="damage-fullscreen-nav"><button class="btn" id="fullPreviousDamageView">← Vista anterior</button><strong id="fullViewCounter">${VIEWS.findIndex(v=>v[0]===d.view)+1} de ${VIEWS.length}</strong><button class="btn" id="fullNextDamageView">Vista siguiente →</button></div><div class="canvas-tools"><span class="hint">Mantén presionado para dibujar; al soltar se detiene.</span><div><button class="btn small" id="undo">Deshacer</button> <button class="btn small" id="redo">Rehacer</button> <button class="btn small danger" id="clearDraw">Limpiar vista</button></div></div></div><button class="btn primary damage-expand" id="fullscreenDamage">⛶ Editar en pantalla completa</button>`);setupDrawing();const moveView=offset=>{persistCanvas();const index=(VIEWS.findIndex(v=>v[0]===d.view)+offset+VIEWS.length)%VIEWS.length;d.view=VIEWS[index][0];save();damageStep()};$$('[data-view]').forEach(b=>b.onclick=()=>{persistCanvas();d.view=b.dataset.view;save();damageStep()});$('#previousDamageView').onclick=()=>moveView(-1);$('#nextDamageView').onclick=()=>moveView(1);$('#fullPreviousDamageView').onclick=()=>moveView(-1);$('#fullNextDamageView').onclick=()=>moveView(1);$('#fullscreenDamage').onclick=()=>setDamageExpanded(true);$('#exitDamageFullscreen').onclick=()=>setDamageExpanded(false);$$('[data-body]').forEach(b=>b.onclick=()=>{if(b.dataset.body===d.body)return;if(Object.values(d.drawings).some(a=>a?.length)&&!confirm('La carrocería actual contiene trazos. Se conservarán temporalmente. ¿Deseas cambiar?'))return;persistCanvas();d.body=b.dataset.body;d.view='01';save();damageStep()});updateDamageEditor()}
let strokes=[],redo=[],damageExpanded=false,resizeDamageCanvas=()=>{};
function updateDamageEditor(){const editor=$('#damageEditor');if(!editor)return;const lateral=['04','05'].includes(state.draft.view),portrait=matchMedia('(orientation: portrait)').matches;editor.classList.toggle('needs-landscape',damageExpanded&&lateral&&portrait);document.body.classList.toggle('damage-editor-open',damageExpanded);requestAnimationFrame(resizeDamageCanvas)}
function setDamageExpanded(open){damageExpanded=open;const editor=$('#damageEditor');if(!editor)return;editor.classList.toggle('is-fullscreen',open);if(open&&screen.orientation?.lock)screen.orientation.lock('landscape').catch(()=>{});if(!open&&screen.orientation?.unlock)screen.orientation.unlock();updateDamageEditor()}
function damageBox(){const c=$('#damageCanvas'),w=$('.canvas-wrap img');if(!c||!w)return null;const b=c.getBoundingClientRect(),n=w.naturalWidth||0,m=w.naturalHeight||0;if(!n||!m||!b.width||!b.height)return null;const k=Math.min(b.width/n,b.height/m),pw=n*k,ph=m*k;return{left:(b.width-pw)/2,top:(b.height-ph)/2,w:pw,h:ph,ox:b.left,oy:b.top};}
function strokePts(ctx,s,B){ctx.strokeStyle='#2563eb';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();s.forEach((p,i)=>{const x=B.left+p.u*B.w,y=B.top+p.v*B.h;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();}
function drawAll(ctx,box){const B=box||damageBox();if(!B)return;ctx.clearRect(0,0,ctx.canvas.width,ctx.canvas.height);ctx.setTransform(1,0,0,1,0,0);ctx.scale(devicePixelRatio,devicePixelRatio);strokes.forEach(s=>strokePts(ctx,s,B));}
function persistCanvas(){if(!$('#damageCanvas'))return;state.draft.drawings[`${state.draft.body}-${state.draft.view}`]=strokes}
function setupDrawing(){const c=$('#damageCanvas'),scale=devicePixelRatio,ctx=c.getContext('2d');strokes=structuredClone(state.draft.drawings[`${state.draft.body}-${state.draft.view}`]||[]);redo=[];let box;resizeDamageCanvas=()=>{const r=c.getBoundingClientRect();if(!r.width||!r.height)return;c.width=Math.round(r.width*scale);c.height=Math.round(r.height*scale);box=damageBox();drawAll(ctx,box)};resizeDamageCanvas();const img=$('.canvas-wrap img');if(img&&!img.complete)img.addEventListener('load',resizeDamageCanvas,{once:true});let active=false,current=[];const p=e=>{const B=damageBox()||box;if(B)box=B;return B?{u:(e.clientX-B.ox-B.left)/B.w,v:(e.clientY-B.oy-B.top)/B.h}:null};c.onpointerdown=e=>{if($('#damageEditor').classList.contains('needs-landscape'))return;const q=p(e);if(!q)return;active=true;current=[q];c.setPointerCapture(e.pointerId);e.preventDefault()};c.onpointermove=e=>{if(!active)return;const q=p(e);if(!q)return;current.push(q);drawAll(ctx,box);if(current.length>1)strokePts(ctx,current,box);e.preventDefault()};const stop=e=>{if(!active)return;active=false;if(current.length>1){strokes.push(current);redo=[];persistCanvas();save()}current=[];try{c.releasePointerCapture(e.pointerId)}catch{}};c.onpointerup=stop;c.onpointercancel=stop;c.onpointerleave=stop;$('#undo').onclick=()=>{if(strokes.length)redo.push(strokes.pop());persistCanvas();save();drawAll(ctx)};$('#redo').onclick=()=>{if(redo.length)strokes.push(redo.pop());persistCanvas();save();drawAll(ctx)};$('#clearDraw').onclick=()=>{if(confirm('¿Limpiar todos los trazos de esta vista?')){strokes=[];redo=[];persistCanvas();save();drawAll(ctx)}};addEventListener('resize',updateDamageEditor);addEventListener('orientationchange',updateDamageEditor)}
function evidenceStep(){const d=state.draft,full=d.photos.length>=15;shell(`<div class="section-title"><span>▣</span><div><h2>Evidencias fotográficas</h2><small class="hint">${d.photos.length} de 15 · orden cronológico.</small></div></div><label class="upload${full?' is-full':''}"><strong>${full?'✓ Evidencias completas':'＋ Tomar o elegir fotografías'}</strong><small class="hint" style="display:block;margin-top:5px">${full?'No se pueden adjuntar más fotografías':'JPG, PNG o WebP · compresión simulada'}</small><input id="photoInput" type="file" accept="image/*" capture="environment" multiple${full?' disabled':''}></label><div class="photo-grid">${d.photos.length?d.photos.map((x,i)=>`<div class="photo"><img src="${x}" alt="Evidencia ${i+1}"><button type="button" data-del-photo="${i}" aria-label="Eliminar evidencia ${i+1}">×</button></div>`).join(''):'<div class="photo-empty">Aún no has adjuntado fotografías.<br>Usa el área de arriba para agregarlas.</div>'}</div><div class="important" style="margin-top:15px"><strong>Recomendación:</strong> documenta los daños principales. Puedes continuar sin completar las 15 fotografías.</div>`);$('#photoInput').onchange=e=>{[...e.target.files].slice(0,15-d.photos.length).forEach(f=>{const r=new FileReader();r.onload=()=>{d.photos.push(r.result);save();evidenceStep()};r.readAsDataURL(f)})};$$('[data-del-photo]').forEach(b=>b.onclick=()=>{d.photos.splice(+b.dataset.delPhoto,1);save();evidenceStep()})}
function diagnosisStep(){const d=state.draft;shell(`<div class="section-title"><span>▧</span><div><h2>Diagnóstico</h2><small class="hint">La evaluación manuscrita es independiente de las 15 evidencias.</small></div></div><div class="form-grid"><div class="field full"><label>Descripción del diagnóstico</label><textarea data-bind="diagnosis" placeholder="Daños observados y trabajos sugeridos...">${d.diagnosis}</textarea></div><div class="field full"><label>Fotografía de evaluación manuscrita</label><input id="diagPhoto" type="file" accept="image/*" capture="environment">${d.diagnosisPhoto?'<span class="success-note">Fotografía adjuntada.</span>':'<small class="hint">Opcional, pero recomendada.</small>'}</div></div>`);$('#diagPhoto').onchange=e=>{const f=e.target.files[0];if(f){const r=new FileReader();r.onload=()=>{d.diagnosisPhoto=r.result;save();diagnosisStep()};r.readAsDataURL(f)}}}
function summaryStep(){const d=state.draft;shell(`<div class="section-title"><span>✓</span><div><h2>Resumen y firma</h2><small class="hint">Revisa antes de crear la orden oficial.</small></div></div><div class="summary-grid"><div class="summary-box"><small>Cliente</small><strong style="display:block">${d.client||d.doc}</strong><span>${d.doc}</span></div><div class="summary-box"><small>Vehículo</small><strong style="display:block">${d.brand} ${d.model} · ${d.color}</strong><span>${d.plate} · ${BODIES.find(b=>b.id===d.body)?.name}</span></div><div class="summary-box"><small>Ingreso</small><strong style="display:block">${d.km||'No registrado'} km</strong><span>Combustible: ${d.fuel||'No registrado'}</span></div><div class="summary-box"><small>Registro</small><strong style="display:block">44/44 checklist</strong><span>${d.photos.length} evidencias · ${Object.values(d.drawings).filter(x=>x?.length).length} vistas marcadas</span></div></div><h3>Firma de recepción</h3><div class="signature"><canvas id="signatureCanvas"></canvas></div><div style="margin:9px 0"><button class="btn small" id="clearSign">Limpiar firma</button></div><label class="toggle-row"><span>Declaro haber revisado la información registrada y acepto las condiciones de recepción del vehículo.</span><input type="checkbox" data-bind="accept" ${d.accept?'checked':''}></label>${(!d.km||!d.fuel)?'<div class="important"><strong>Información de ingreso incompleta:</strong> kilometraje y/o combustible no registrado. Puedes confirmar bajo responsabilidad del asesor.</div>':''}`);setupSignature()}
function setupSignature(){const c=$('#signatureCanvas'),r=c.getBoundingClientRect(),ctx=c.getContext('2d'),sc=devicePixelRatio;c.width=r.width*sc;c.height=r.height*sc;ctx.scale(sc,sc);if(state.draft.signature){const im=new Image();im.onload=()=>ctx.drawImage(im,0,0,r.width,r.height);im.src=state.draft.signature}let active=false,last;const pos=e=>{const b=c.getBoundingClientRect();return{x:e.clientX-b.left,y:e.clientY-b.top}};c.onpointerdown=e=>{active=true;last=pos(e);c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!active)return;const p=pos(e);ctx.strokeStyle='#17212b';ctx.lineWidth=2.5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p};c.onpointerup=e=>{active=false;state.draft.signature=c.toDataURL();save()};c.onpointercancel=()=>active=false;$('#clearSign').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);state.draft.signature='';save()}}
function createOrder(){return Api.create()}
function detail(){const o=state.orders.find(x=>x.id===state.selected)||state.orders[0],tabs={summary:'Resumen',quote:'Cotización',parts:'Repuestos',control:'Control final',audit:'Historial'};let body=state.tab==='summary'?summary(o):state.tab==='quote'?quote(o):state.tab==='parts'?partsView(o):state.tab==='control'?control(o):history(o);$('#app').innerHTML=`<div class="detail-hero"><div><button class="btn small" data-go="orders">← Volver</button><h1>${o.number}</h1><span>${o.brand} ${o.model} · ${o.color} · ${o.plate}</span></div><div class="field"><label>Estado actual</label><select id="statusSelect">${Object.entries(STAT).map(([k,v])=>`<option value="${k}" ${o.status===k?'selected':''}>${v}</option>`)}</select></div></div><div class="tabs">${Object.entries(tabs).map(([k,v])=>`<button class="tab ${state.tab===k?'active':''}" data-tab="${k}">${v}</button>`).join('')}</div>${body}`;wireRoutes();$$('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='quote'&&state.tab!==b.dataset.tab)quoteFocusRequested=true;state.tab=b.dataset.tab;save();detail()});$('#statusSelect').onchange=e=>changeStatus(o,e.target.value);wireDetail(o);if(state.tab==='quote'&&quoteFocusRequested){quoteFocusRequested=false;requestAnimationFrame(()=>$('table[data-key="labor"] input[data-col="d"]')?.focus())}}
function summary(o){return `<div class="grid-2"><section class="card"><div class="card-header"><h2>Información del caso</h2></div><div class="card-body form-grid"><div><small class="hint">Cliente</small><strong style="display:block">${o.client}</strong></div><div><small class="hint">Documento</small><strong style="display:block">${o.doc}</strong></div><div><small class="hint">Vehículo</small><strong style="display:block">${o.brand} ${o.model}</strong></div><div><small class="hint">Color / carrocería</small><strong style="display:block">${o.color} · ${BODIES.find(b=>b.id===o.body)?.name}</strong></div><div><small class="hint">Modalidad</small><strong style="display:block">${o.mode}</strong></div><div><small class="hint">Código público</small><strong style="display:block">${o.code}</strong></div></div></section><aside class="card"><div class="card-header"><h2>Avance</h2></div><div class="card-body"><strong style="font-size:34px">${PROGRESS[o.status]}%</strong><div class="bar" style="margin:14px 0"><i style="width:${PROGRESS[o.status]}%"></i></div><p class="hint">Etapa alcanzada; no representa avance físico exacto.</p><button class="btn" id="receptionPdf">Checklist de Ingreso</button></div></aside></div>`}
function quote(o){const insurer=o.mode!=='Particular',full=o.fullQuote||!insurer;return `<section class="card"><div class="card-header"><h2>Cotización · ${o.mode}</h2><span class="status ${o.quote==='APROBADA'?'green':o.quote==='ENVIADA'?'blue':'amber'}">${o.quote}</span></div><div class="card-body">${insurer?`<div class="important">La cotización oficial se gestiona en la plataforma de la aseguradora. Registra aquí el seguimiento.</div><label class="toggle-row"><span>Registrar cotización completa dentro de PARAUTOS</span><input type="checkbox" id="fullQuote" ${o.fullQuote?'checked':''}></label>`:''}${full?quoteTables(o):''}<div class="form-grid"><div class="field"><label>Fecha de envío</label><input type="date" id="sentDate" value="${o.sentDate||''}"></div><div class="field"><label>Fecha de aprobación</label><input type="date" id="approvedDate" value="${o.approvedDate||''}"></div></div><div style="display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;margin-top:16px"><button class="btn" id="quotePdf" ${full?'':'disabled'}>Cotización formal PDF</button><button class="btn" id="workPdf">Orden de servicio sin precios</button><button class="btn" id="markSent">Marcar enviada</button><button class="btn primary" id="markApproved">Marcar aprobada</button></div></div></section>`}
function quoteTables(o){return `<label class="toggle-row"><span>Este servicio no requiere repuestos ni insumos</span><input type="checkbox" id="noParts" ${o.noParts?'checked':''}></label>${itemTable('Mano de obra','labor',o.labor)}${o.noParts?'':itemTable('Repuestos e insumos','quoteParts',o.quoteParts)}<div class="quote-total"><span>Total sin IGV</span><strong>S/ ${[...o.labor,...(o.noParts?[]:o.quoteParts)].reduce((a,x)=>a+(+x.q||0)*(+x.p||0),0).toFixed(2)}</strong></div><div class="important">La presente cotización no contempla IGV.</div>`}
function itemTable(title,key,items){return `<h3>${title}</h3><div class="table-wrap"><table class="data-table quote-table" data-key="${key}"><thead><tr><th>Descripción (Enter crea otra fila)</th><th>Cantidad</th><th>Precio unitario</th><th>Subtotal</th><th></th></tr></thead><tbody>${[...items,{d:'',q:1,p:''}].map((x,i)=>`<tr><td><input data-col="d" data-i="${i}" value="${x.d||''}" placeholder="Escribe y presiona Enter"></td><td><input data-col="q" data-i="${i}" type="number" min="0" value="${x.q??1}"></td><td><input data-col="p" data-i="${i}" type="number" min="0" value="${x.p??''}"></td><td>S/ ${((+x.q||0)*(+x.p||0)).toFixed(2)}</td><td><button class="btn small" data-del-item="${i}">×</button></td></tr>`).join('')}</tbody></table></div>`}
function partsView(o){const rec=o.parts.filter(p=>p.status==='RECIBIDO').length,llego=p=>p.status==='RECIBIDO';
return `<section class="card"><div class="card-header"><h2>Seguimiento de repuestos</h2><span>${rec} de ${o.parts.length} recibidos</span></div><div class="card-body"><small class="hint">Los repuestos se toman de la pestaña Cotización. Aquí solo se registra si llegaron.</small>${o.noParts?'<div class="important" style="margin-top:12px">La cotización está marcada como servicio sin repuestos ni insumos.</div>':''}<div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>Descripción</th><th>Cant.</th><th>¿Llegó?</th><th>Última actualización</th></tr></thead><tbody>${o.parts.length?o.parts.map(p=>`<tr><td>${p.name}</td><td>${p.qty??1}</td><td><label class="part-check"><input type="checkbox" data-part-check value="${p.name}" ${llego(p)?'checked':''}><span>${llego(p)?'Recibido':'En espera'}</span></label></td><td>${p.updated||'Sin registrar'}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No hay repuestos en la cotización de esta orden.</td></tr>'}</tbody></table></div></div></section>`}
// Conceptos de mano de obra con verificacion binaria: solo.checked o sin marcar.
function controlRows(o){return (Array.isArray(o.labor)?o.labor:[]).filter(x=>String(x.d||'').trim())}
function controlPendientes(o){const rs=controlRows(o);o.controlPendientes=rs.filter(x=>!x.ok).length;return rs.length}
// Retirar una verificacion ya registrada deshace el control y devuelve la orden
// a EN_REPARACION. Una orden ya entregada no se toca: no se des-entrega un vehiculo.
function anularControl(o,motivo){o.controlDone=false;o.controlAt=null;o.controlPendientes=controlPendientes(o);
  const av={when:new Date().toLocaleString(),user:state.currentUser?.nombres||'Asesor'};
  if(o.status==='LISTA_PARA_ENTREGA'){const prev=STAT[o.status];o.status='EN_REPARACION';
   state.audit.unshift({...av,event:`${o.number}: ${prev} → ${STAT[o.status]}`})}
  state.audit.unshift({...av,event:`${o.number}: control final anulado (${motivo})`})}
function control(o){const pending=o.parts.some(p=>p.status!=='RECIBIDO');
const rows=controlRows(o).map((x,i)=>({x,i:o.labor.indexOf(x)})),sinMano=!rows.length,bloq=pending||sinMano,
marcados=rows.filter(r=>r.x.ok).length,todos=rows.length>0&&marcados===rows.length,pendientes=rows.length-marcados;
return `<section class="card"><div class="card-header"><h2>Control final obligatorio</h2><span>${o.controlDone?(pendientes?`Completado · ${pendientes} pendiente${pendientes===1?'':'s'}`:'Completado'):'Pendiente'}</span></div><div class="card-body">${pending?'<div class="important"><strong>Bloqueado:</strong> aún existen repuestos sin recibir.</div>':''}${sinMano?'<div class="important">No hay mano de obra registrada. Registra los conceptos en la pestaña Cotización para poder verificar el control final.</div>':''}${sinMano?'':`<div class="mark-all-row"><label class="part-check"><input type="checkbox" id="markAllFinal" ${todos?'checked':''} ${bloq?'disabled':''}><span>Marcar todos · ${marcados} de ${rows.length}</span></label></div>`}${rows.map(r=>`<label class="control-check"><input type="checkbox" data-labor-ok="${r.i}" ${r.x.ok?'checked':''} ${bloq?'disabled':''}><span>${r.x.d}</span></label>`).join('')}<div style="display:flex;justify-content:flex-end;margin-top:15px"><button class="btn primary" id="finishControl" ${bloq?'disabled':''}>Registrar control final</button></div></div></section>`}
function history(o){return `<section class="card"><div class="card-header"><h2>Historial resumido</h2></div><div class="card-body"><div class="list-row"><span class="vehicle-tag">1</span><div><strong>Orden registrada</strong><small>${o.advisor}</small></div><div>${o.number}</div><span class="status green">Completado</span></div><div class="list-row"><span class="vehicle-tag">2</span><div><strong>Estado actual</strong><small>Cambio manual auditado</small></div><div>${STAT[o.status]}</div><span class="status ${cls(o.status)}">Activo</span></div></div></section>`}
function changeStatus(o,next){if(next==='LISTA_PARA_ENTREGA'&&(!o.controlDone||o.parts.some(p=>p.status!=='RECIBIDO'))){toast('Completa el control final y recibe todos los repuestos');return detail()}if(next==='ENTREGADA'&&o.status!=='LISTA_PARA_ENTREGA'){toast('Primero debe quedar lista para entrega');return detail()}if(!confirm(`Cambiar de “${STAT[o.status]}” a “${STAT[next]}”?`))return detail();state.audit.unshift({when:new Date().toLocaleString(),event:`${o.number}: ${STAT[o.status]} → ${STAT[next]}`,user:state.currentUser?.nombres||'Asesor'});o.status=next;save();detail()}
function wireDetail(o){$('#fullQuote')?.addEventListener('change',e=>{o.fullQuote=e.target.checked;save();detail()});$('#noParts')?.addEventListener('change',e=>{o.noParts=e.target.checked;syncParts(o);save();detail()});$$('.quote-table').forEach(t=>{const key=t.dataset.key;t.querySelectorAll('input').forEach(inp=>{inp.onchange=()=>{const i=+inp.dataset.i;if(!o[key][i])o[key][i]={d:'',q:1,p:''};o[key][i][inp.dataset.col]=inp.dataset.col==='d'?inp.value:+inp.value;if(key==='quoteParts')syncParts(o);save();detail()};inp.onkeydown=e=>{if(e.key==='Enter'&&inp.dataset.col==='d'){e.preventDefault();const i=+inp.dataset.i;if(!o[key][i])o[key][i]={d:inp.value,q:1,p:''};else o[key][i].d=inp.value;if(key==='quoteParts')syncParts(o);save();detail();setTimeout(()=>document.querySelector(`table[data-key="${key}"] input[data-i="${i+1}"][data-col="d"]`)?.focus(),0)}}});t.querySelectorAll('[data-del-item]').forEach(b=>b.onclick=()=>{o[key].splice(+b.dataset.delItem,1);if(key==='quoteParts')syncParts(o);save();detail()})});$('#markSent')?.addEventListener('click',()=>{o.quote='ENVIADA';o.sentDate=$('#sentDate')?.value||new Date().toISOString().slice(0,10);o.status='ESPERA_APROBACION';save();toast('Cotización marcada como enviada');detail()});$('#markApproved')?.addEventListener('click',()=>{o.quote='APROBADA';o.approvedDate=$('#approvedDate')?.value||new Date().toISOString().slice(0,10);o.status=o.noParts||!o.parts.length?'EN_REPARACION':'ESPERA_REPUESTOS';save();detail()});$$('[data-part-check]').forEach(e=>e.onchange=()=>{const p=o.parts.find(x=>x.name===e.value);if(!p)return;p.status=e.checked?'RECIBIDO':'PENDIENTE_SOLICITAR';p.updated=new Date().toLocaleDateString();save();detail()});
$$('[data-labor-ok]').forEach(e=>e.onchange=()=>{const x=o.labor[+e.dataset.laborOk];if(!x)return;
 const estaba=!!x.ok;x.ok=e.checked;
 if(estaba&&!x.ok&&o.controlDone)anularControl(o,'se retiro una verificacion');
 controlPendientes(o);save();detail()});
$('#markAllFinal')?.addEventListener('change',e=>{const on=e.target.checked,rs=controlRows(o);
 let retirados=0;rs.forEach(x=>{if(on)x.ok=true;else{if(x.ok)retirados++;x.ok=false}});
 if(!on&&o.controlDone)anularControl(o,retirados?`se desmarcaron ${retirados} verificaciones`:'se desmarco todo');
 controlPendientes(o);save();detail()});
const _m=$('#markAllFinal');if(_m){const r=controlRows(o),n=r.filter(x=>x.ok).length;_m.indeterminate=n>0&&n<r.length}$('#finishControl')?.addEventListener('click',()=>{const rs=controlRows(o);
if(!rs.length)return toast('Registra mano de obra antes del control final');
if(o.parts.some(p=>p.status!=='RECIBIDO'))return toast('Aun existen repuestos sin recibir');
const marc=rs.filter(x=>x.ok).length,pend=rs.length-marc;
o.controlDone=true;o.controlAt=new Date().toISOString();o.controlPendientes=pend;o.status='LISTA_PARA_ENTREGA';
state.audit.unshift({when:new Date().toLocaleString(),event:`${o.number}: control final registrado (${marc} de ${rs.length} verificados${pend?`, ${pend} pendientes`:''})`,user:state.currentUser?.nombres||'Asesor'});
save();toast(pend?`Control final registrado con ${pend} pendiente${pend===1?'':'s'}`:'Control final aprobado');detail()});$('#quotePdf')?.addEventListener('click',()=>documentPreview(o,'Cotización formal',true));$('#workPdf')?.addEventListener('click',()=>documentPreview(o,'Orden de servicio',false));$('#receptionPdf')?.addEventListener('click',()=>openReceptionSheet(o))}
function documentPreview(o,title,prices){const labor=Array.isArray(o.labor)?o.labor:[],rows=prices?[...labor,...(Array.isArray(o.quoteParts)?o.quoteParts:[])]:labor,aviso=prices?'No se registraron conceptos para cotizar.':'No se registraron trabajos de mano de obra en esta orden.';$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><strong>Vista previa · una hoja A4</strong><div><button class="btn" id="printDoc">Imprimir / guardar PDF</button> <button class="btn" id="closeModal">Cerrar</button></div></div><div class="modal-body doc-preview"><article class="a4"><img class="doc-logo" src="assets/logo_parautos.svg"><div class="doc-rule"></div><h1 class="doc-title">${title}</h1><p><strong>B & P Service S.A.C. | PARAUTOS</strong><br>RUC 20560170549 · Av. América Norte N.° 2404, Trujillo<br>952 394 849 · asesordeservicios@parautosperú.com</p><table class="doc-table"><tr><th>Orden</th><td>${o.number}</td><th>Fecha</th><td>${new Date().toLocaleDateString()}</td></tr><tr><th>Cliente</th><td>${o.client}</td><th>Documento</th><td>${o.doc}</td></tr><tr><th>Vehículo</th><td>${o.brand} ${o.model} · ${o.color}</td><th>Placa</th><td>${o.plate}</td></tr></table>${rows.length?`<table class="doc-table"><thead><tr><th>Descripción</th><th>Cant.</th>${prices?'<th>P. unit.</th><th>Subtotal</th>':''}</tr></thead><tbody>${rows.map(x=>`<tr><td>${x.d}</td><td>${x.q}</td>${prices?`<td>S/ ${(+x.p||0).toFixed(2)}</td><td>S/ ${((+x.q||0)*(+x.p||0)).toFixed(2)}</td>`:''}</tr>`).join('')}</tbody></table>`:`<div class="doc-note">${aviso}</div>`}${prices?'<p><strong>La presente cotización no contempla IGV.</strong></p>':''}<div style="margin-top:80px;display:flex;justify-content:space-around"><span>____________________<br>Asesor responsable</span><span>____________________<br>Cliente</span></div></article></div></div></div>`;$('#closeModal').onclick=()=>$('#modalRoot').innerHTML='';$('#printDoc').onclick=()=>print()}
function quotes(){const list=state.orders.filter(o=>['PENDIENTE','ENVIADA','NO_APROBADA'].includes(o.quote));$('#app').innerHTML=head('Cotizaciones y pendientes','Las alertas permanecen activas hasta marcar una cotización como enviada.')+`<section class="card">${list.length?list.map(orderRow).join(''):'<div class="empty">No existen cotizaciones pendientes.</div>'}</section>`;wireRoutes()}
function parts(){const list=state.orders.filter(o=>o.parts?.length);$('#app').innerHTML=head('Repuestos','Seguimiento operativo de solicitudes y recepción.')+`<section class="card">${list.map(o=>`<div class="list-row"><span class="vehicle-tag">▧</span><div><strong>${o.brand} ${o.model} · ${o.color}</strong><small>${o.plate} · ${o.number}</small></div><div>${o.parts.filter(p=>p.status==='RECIBIDO').length} de ${o.parts.length} recibidos</div><button class="btn small" data-open="${o.id}" data-goto="parts">Gestionar</button></div>`).join('')||'<div class="empty">No hay repuestos registrados.</div>'}</section>`;wireRoutes()}
const reportEscape=value=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const reportDate=(value,index)=>value||`2026-09-${String(22+index).padStart(2,'0')}`;
function downloadReportCsv(filename,columns,rows){const quote=value=>`"${String(value??'').replaceAll('"','""')}"`;const csv='\uFEFF'+[columns.map(column=>quote(column.label)).join(';'),...rows.map(row=>columns.map(column=>quote(row[column.key])).join(';'))].join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function previewReport(title,columns,rows){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><strong>${title}</strong><div><button class="btn" id="printReport">Imprimir / guardar PDF</button> <button class="btn" id="closeReport">Cerrar</button></div></div><div class="modal-body"><p class="hint">Vista de demostración generada desde datos locales.</p><div class="table-wrap"><table class="data-table"><thead><tr>${columns.map(column=>`<th>${column.label}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(column=>`<td>${reportEscape(row[column.key])}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${columns.length}" class="empty">No hay datos para los filtros seleccionados.</td></tr>`}</tbody></table></div></div></div></div>`;$('#closeReport').onclick=()=>$('#modalRoot').innerHTML='';$('#printReport').onclick=()=>print()}
function quoteReportRows(){return state.orders.map((order,index)=>({number:order.number,vehicle:`${order.brand} ${order.model} · ${order.color}`,plate:order.plate,client:order.client,mode:order.mode,claim:order.claim||'—',state:order.quote||'PENDIENTE',created:reportDate(order.createdAt,index),sent:order.sentDate||'Sin enviar',approved:order.approvedDate||'Sin aprobar',days:order.quote==='PENDIENTE'?index+1:order.quote==='ENVIADA'?index+2:0})).filter(row=>['PENDIENTE','ENVIADA'].includes(row.state))}
function partReportRows(){return state.orders.flatMap((order,orderIndex)=>(order.parts||[]).map((part,partIndex)=>({number:order.number,vehicle:`${order.brand} ${order.model} · ${order.color}`,plate:order.plate,client:order.client,item:part.name||part.d||'Insumo sin descripción',type:part.type||'REPUESTO',quantity:part.qty||1,state:part.status||'PENDIENTE_SOLICITAR',requested:part.requestedAt||reportDate(null,orderIndex+partIndex),received:part.status==='RECIBIDO'?(part.updated||'Registrado'):'Pendiente',days:part.status==='RECIBIDO'?0:orderIndex+partIndex+1}))).filter(row=>row.state!=='RECIBIDO')}
function reports(){if(reportTab==='quotes')return quoteReport();if(reportTab==='parts')return partReport();const total=Math.max(1,state.orders.length),count=status=>state.orders.filter(order=>order.status===status).length;$('#app').innerHTML=head('Dashboard y reportes','Indicadores operativos para priorizar el trabajo del taller.')+`<div class="cards"><div class="card metric"><small>Órdenes activas</small><strong>${state.orders.filter(order=>!['ENTREGADA','CANCELADA'].includes(order.status)).length}</strong></div><div class="card metric amber"><small>Cotizaciones pendientes</small><strong>${quoteReportRows().length}</strong></div><div class="card metric blue"><small>Espera de repuestos</small><strong>${count('ESPERA_REPUESTOS')}</strong></div><div class="card metric green"><small>Listas para entrega</small><strong>${count('LISTA_PARA_ENTREGA')}</strong></div></div><div class="grid-2"><section class="card"><div class="card-header"><h2>Órdenes por modalidad</h2></div><div class="card-body">${['Particular','Mapfre','La Positiva','Rímac','Pacífico'].map(mode=>{const amount=state.orders.filter(order=>order.mode===mode).length;return `<div class="chart-row"><span>${mode}</span><div class="bar"><i style="width:${amount/total*100}%"></i></div><b>${amount}</b></div>`}).join('')}</div></section><section class="card report-actions"><div class="card-header"><h2>Reportes operativos</h2></div><div class="card-body"><button class="report-choice" data-report="quotes"><strong>Cotizaciones pendientes</strong><span>Controlar envíos y aprobaciones.</span><b>Ver reporte →</b></button><button class="report-choice" data-report="parts"><strong>Repuestos e insumos pendientes</strong><span>Priorizar solicitudes y recepciones.</span><b>Ver reporte →</b></button></div></section></div>`;$$('[data-report]').forEach(button=>button.onclick=()=>{reportTab=button.dataset.report;reports()})}
function quoteReport(){const columns=[{key:'number',label:'Orden'},{key:'vehicle',label:'Vehículo'},{key:'plate',label:'Placa'},{key:'client',label:'Cliente'},{key:'mode',label:'Modalidad'},{key:'claim',label:'Siniestro'},{key:'state',label:'Estado'},{key:'created',label:'Creada'},{key:'sent',label:'Enviada'},{key:'days',label:'Días pendientes'}];$('#app').innerHTML=head('Cotizaciones pendientes','Identifica cotizaciones que deben enviarse o requieren seguimiento.',`<button class="btn" id="backReports">← Dashboard</button>`)+`<div class="filters report-filters"><div class="field"><label>Estado<select id="quoteState"><option value="">Pendiente y enviada</option><option>PENDIENTE</option><option>ENVIADA</option></select></label></div><div class="field"><label>Modalidad<select id="quoteMode"><option value="">Todas las modalidades</option>${[...new Set(state.orders.map(order=>order.mode))].map(mode=>`<option>${mode}</option>`).join('')}</select></label></div><div class="field"><label>Desde<input id="quoteFrom" type="date"></label></div></div><div class="report-toolbar"><small id="quoteCount" class="hint"></small><div><button class="btn" id="quoteCsv">Exportar CSV</button> <button class="btn primary" id="quotePrint">Vista de impresión</button></div></div><section class="card table-wrap"><table class="data-table"><thead><tr>${columns.map(column=>`<th>${column.label}</th>`).join('')}</tr></thead><tbody id="quoteReportRows"></tbody></table></section>`;let visible=[];const update=()=>{visible=quoteReportRows().filter(row=>(!$('#quoteState').value||row.state===$('#quoteState').value)&&(!$('#quoteMode').value||row.mode===$('#quoteMode').value)&&(!$('#quoteFrom').value||row.created>=$('#quoteFrom').value));$('#quoteCount').textContent=`${visible.length} cotización(es) por atender`;$('#quoteReportRows').innerHTML=visible.map(row=>`<tr>${columns.map(column=>`<td>${reportEscape(row[column.key])}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${columns.length}" class="empty">No hay cotizaciones con esos filtros.</td></tr>`};$('#backReports').onclick=()=>{reportTab='dashboard';reports()};$('#quoteState').onchange=update;$('#quoteMode').onchange=update;$('#quoteFrom').onchange=update;$('#quoteCsv').onclick=()=>downloadReportCsv('parautos-cotizaciones-pendientes.csv',columns,visible);$('#quotePrint').onclick=()=>previewReport('Cotizaciones pendientes',columns,visible);update()}
function partReport(){const columns=[{key:'number',label:'Orden'},{key:'vehicle',label:'Vehículo'},{key:'plate',label:'Placa'},{key:'client',label:'Cliente'},{key:'item',label:'Insumo'},{key:'type',label:'Tipo'},{key:'quantity',label:'Cantidad'},{key:'state',label:'Estado'},{key:'requested',label:'Solicitud'},{key:'days',label:'Días pendientes'}];$('#app').innerHTML=head('Repuestos e insumos pendientes','Controla qué insumos faltan y a qué vehículo corresponden.',`<button class="btn" id="backReports">← Dashboard</button>`)+`<div class="filters report-filters"><div class="field"><label>Estado<select id="partState"><option value="">Todos los pendientes</option><option>PENDIENTE_SOLICITAR</option><option>SOLICITADO</option></select></label></div><div class="field"><label>Tipo<select id="partType"><option value="">Todos los tipos</option><option>REPUESTO</option><option>PINTURA</option><option>OTRO</option></select></label></div><div class="field"><label>Desde<input id="partFrom" type="date"></label></div></div><div class="report-toolbar"><small id="partCount" class="hint"></small><div><button class="btn" id="partCsv">Exportar CSV</button> <button class="btn primary" id="partPrint">Vista de impresión</button></div></div><section class="card table-wrap"><table class="data-table"><thead><tr>${columns.map(column=>`<th>${column.label}</th>`).join('')}</tr></thead><tbody id="partReportRows"></tbody></table></section>`;let visible=[];const update=()=>{visible=partReportRows().filter(row=>(!$('#partState').value||row.state===$('#partState').value)&&(!$('#partType').value||row.type===$('#partType').value)&&(!$('#partFrom').value||row.requested>=$('#partFrom').value));$('#partCount').textContent=`${visible.length} insumo(s) pendiente(s)`;$('#partReportRows').innerHTML=visible.map(row=>`<tr>${columns.map(column=>`<td>${reportEscape(row[column.key])}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${columns.length}" class="empty">No hay insumos con esos filtros.</td></tr>`};$('#backReports').onclick=()=>{reportTab='dashboard';reports()};$('#partState').onchange=update;$('#partType').onchange=update;$('#partFrom').onchange=update;$('#partCsv').onclick=()=>downloadReportCsv('parautos-repuestos-pendientes.csv',columns,visible);$('#partPrint').onclick=()=>previewReport('Repuestos e insumos pendientes',columns,visible);update()}
function audit(){const events=[...state.audit,{when:'23/09/2026 08:30',event:'Inicio de sesión local',user:state.currentUser?.nombres||'Asesor'}].map(event=>({...event,action:auditAction(event.event)}));const users=[...new Set(events.map(event=>event.user).filter(Boolean))];const date=value=>{const match=String(value||'').match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);return match?new Date(+match[3],+match[2]-1,+match[1]):null};$('#app').innerHTML=head('Auditoría','Consulta las acciones registradas por los usuarios.')+`<section class="audit-filter-panel"><div class="audit-filter-head"><div><p class="eyebrow">BÚSQUEDA Y FILTROS</p><h2>Filtrar eventos registrados</h2><p>Combina los criterios para localizar acciones específicas.</p></div><button class="btn" id="clearAuditFilters">Limpiar filtros</button></div><div class="audit-filters"><div class="field audit-search"><label>Buscar orden, placa o evento<input id="auditSearch" placeholder="Ej. OS-2026, repuesto o cambio de estado"></label></div><div class="field"><label>Usuario<select id="auditUser"><option value="">Todos los usuarios</option>${users.map(user=>`<option>${user}</option>`).join('')}</select></label></div><div class="field"><label>Acción<select id="auditAction"><option value="">Todas las acciones</option>${['Creación de orden','Cotización','Repuestos','Cambio de estado','Control final','Otro'].map(action=>`<option>${action}</option>`).join('')}</select></label></div><div class="field"><label>Periodo<select id="auditPeriod"><option value="">Todo el historial</option><option value="today">Hoy</option><option value="week">Últimos 7 días</option></select></label></div><div class="audit-date-range"><div class="field"><label>Desde<input id="auditFrom" type="date"></label></div><div class="field"><label>Hasta<input id="auditTo" type="date"></label></div></div></div></section><div class="audit-result-bar"><span class="audit-result-dot"></span><small id="auditCount"></small></div><section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha y hora</th><th>Acción</th><th>Evento</th><th>Usuario</th></tr></thead><tbody id="auditRows"></tbody></table></div></section>`;const update=()=>{const search=$('#auditSearch').value.trim().toLowerCase(),user=$('#auditUser').value,action=$('#auditAction').value,period=$('#auditPeriod').value,from=$('#auditFrom').value?new Date(`${$('#auditFrom').value}T00:00:00`):null,to=$('#auditTo').value?new Date(`${$('#auditTo').value}T23:59:59`):null,now=new Date(),week=new Date(now);week.setDate(now.getDate()-7);const visible=events.filter(event=>{const when=date(event.when);return(!search||`${event.event} ${event.user}`.toLowerCase().includes(search))&&(!user||event.user===user)&&(!action||event.action===action)&&(!from||when&&when>=from)&&(!to||when&&when<=to)&&(!period||when&&(period==='today'?when.toDateString()===now.toDateString():when>=week))});$('#auditCount').textContent=`${visible.length} evento(s) encontrado(s)`;$('#auditRows').innerHTML=visible.map(event=>`<tr><td>${event.when}</td><td>${event.action}</td><td>${event.event}</td><td>${event.user||'Sistema'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No hay eventos con los filtros seleccionados.</td></tr>'};['auditSearch','auditUser','auditAction','auditPeriod','auditFrom','auditTo'].forEach(id=>{const field=$(`#${id}`);field.oninput=update;field.onchange=update});$('#clearAuditFilters').onclick=()=>{['auditSearch','auditUser','auditAction','auditPeriod','auditFrom','auditTo'].forEach(id=>{$(`#${id}`).value=''});update()};update()}
function auditAction(event){const text=String(event||'').toLowerCase();if(text.includes('orden creada')||text.includes('orden registrada'))return'Creación de orden';if(text.includes('quote')||text.includes('cotización')||text.includes('cotizacion'))return'Cotización';if(text.includes('repuesto')||text.includes('parts'))return'Repuestos';if(text.includes('control'))return'Control final';if(text.includes('estado')||text.includes('→'))return'Cambio de estado';return'Otro'}
function pendingModal(){const p=state.orders.filter(o=>o.quote==='PENDIENTE');if(!p.length)return;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><strong>Cotizaciones pendientes de envío (${p.length})</strong><button class="btn" id="closePending">Ahora no</button></div><div class="modal-body"><div class="important"><strong>Alerta operativa:</strong> tienes ${p.length} cotización(es) pendiente(s) por enviar. Estas alertas permanecerán activas hasta actualizar cada caso.</div>${p.map(orderRow).join('')}<div style="display:flex;justify-content:flex-end;margin-top:16px"><button class="btn primary" id="viewPending">Ver cotizaciones</button></div></div></div></div>`;$('#closePending').onclick=()=>$('#modalRoot').innerHTML='';$('#viewPending').onclick=()=>{state.route='quotes';$('#modalRoot').innerHTML='';save();render()};wireRoutes()}
$('#alertButton').onclick=pendingModal;
// Render functions are reused; business commands are bound by the API adapter.
wireDetail=wireApiDetail;
Api.init().then(async () => {
    try { state.currentUser = await Api.getCurrentUser(); updateUserUI(); if(localStorage.getItem('parautos-apf2-show-pending-alert')==='true'){localStorage.removeItem('parautos-apf2-show-pending-alert');pendingModal();} } catch(e) { console.error(e); }
});

function updateUserUI() {
    if(!state.currentUser) return;
    const card=$('.session-card');
    card.querySelector('strong').textContent=state.currentUser.nombres;
    card.querySelector('small').textContent=state.currentUser.idRol===1?'Administrador':'Asesor';
    $('.top-actions .avatar').textContent=state.currentUser.nombres.split(' ').map(n=>n[0]).join('').substring(0,2).toUpperCase();
    $$('[data-admin-only]').forEach(item=>item.hidden=!isAdmin());
}

